class Solution {
public:
    long long distinctNames(std::vector<std::string>& ideas) {
        std::unordered_set<std::string> groups[26];
        for (const auto& w : ideas) {
            groups[w[0] - 'a'].insert(w.substr(1));
        }
        long long ans = 0;
        for (int i = 0; i < 26; ++i) {
            for (int j = i + 1; j < 26; ++j) {
                long long common = 0;
                for (const auto& suf : groups[i]) {
                    if (groups[j].count(suf)) ++common;
                }
                ans += 2 * (groups[i].size() - common) * (groups[j].size() - common);
            }
        }
        return ans;
    }
};

class Solution {
    public long distinctNames(String[] ideas) {
        java.util.HashSet<String>[] groups = new java.util.HashSet[26];
        for (int i = 0; i < 26; i++) groups[i] = new java.util.HashSet<>();
        for (String w : ideas) {
            groups[w.charAt(0) - 'a'].add(w.substring(1));
        }
        long ans = 0;
        for (int i = 0; i < 26; i++) {
            for (int j = i + 1; j < 26; j++) {
                long common = 0;
                for (String suf : groups[i]) {
                    if (groups[j].contains(suf)) common++;
                }
                ans += 2 * (groups[i].size() - common) * (groups[j].size() - common);
            }
        }
        return ans;
    }
}

var distinctNames = function(ideas) {
    const groups = Array.from({ length: 26 }, () => new Set());
    for (const w of ideas) {
        groups[w.charCodeAt(0) - 97].add(w.slice(1));
    }
    let ans = 0;
    for (let i = 0; i < 26; i++) {
        for (let j = i + 1; j < 26; j++) {
            let common = 0;
            for (const suf of groups[i]) {
                if (groups[j].has(suf)) common++;
            }
            ans += 2 * (groups[i].size - common) * (groups[j].size - common);
        }
